package compile

// Rendered views (Designs/SddGraph DD-1, DD-2): the graph is the source of
// truth; phase markdown is a projection regenerated by compile, never
// hand-edited, never parsed back. Every generated file carries a marker
// naming the graph and the regenerating command, and the renderer REFUSES to
// overwrite any existing file that lacks the marker — that one rule is both
// the transition guard (a v1 hand-authored phase doc is never clobbered by
// accident; conversion takes it over explicitly, task 2.5) and the
// frozen-view refusal for hand-authored documents (a completed v1 phase's
// doc, anchored by a frozen review, is exactly such a file). Generated views
// have their own frozen-view rule (DD-2, task 4.1): a view rendered while
// every node in it was CLOSED (GREEN + covered by a passing frozen full
// review gate, the D-0022 completion-grade predicate) carries the
// frozen-view marker, and a later render that would CHANGE such a file is
// refused — byte-identical re-renders stay no-ops, so compile remains
// runnable on a completed plan. A legitimately reopened phase (a finding
// demoted a node after its gate recorded) requires removing the frozen view
// explicitly; the refusal names that escape.
//
// The plan README is treated differently from phase docs: its prose sections
// (Overview, Non-Goals, ...) and frontmatter are plan identity the graph
// does not hold, so the renderer performs exactly two surgical edits —
// initializing empty phases[] or refreshing statuses of proven graph-owned
// entries, and
// upserting one marker-delimited `## Graph View` section — and otherwise
// preserves the file byte-for-byte. Non-rendered (v1) phase entries retain
// their ownership and bytes; merging their membership is conversion's job.

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
	"unicode/utf8"

	"github.com/danweinerdev/claude-sdd-planner/v2/internal/graph/model"
	"github.com/danweinerdev/claude-sdd-planner/v2/internal/graph/states"
	"github.com/danweinerdev/claude-sdd-planner/v2/internal/rules"
	istore "github.com/danweinerdev/claude-sdd-planner/v2/internal/store"
	"github.com/danweinerdev/claude-sdd-planner/v2/internal/vcs"
	"gopkg.in/yaml.v3"
)

// frozenViewMarker marks a generated view rendered while every node in it
// was closed. Its presence turns content-changing regeneration into a
// refusal (DD-2's frozen-view invariant).
const frozenViewMarker = "<!-- FROZEN VIEW — every node in this phase is closed: GREEN and covered by a passing frozen full review gate. This projection is history; a render that would change it is refused. -->"

// revExistsMemoRepo memoizes RevisionExists per revision, local to one
// renderViews call — production's vcs.EnableMemoization is opt-in and
// process-lifetime, but renderViews must not depend on it: preflightViews
// and the write pass both render every closed phase and would otherwise
// probe the same checkpoint revision twice per phase, and sibling phases
// sharing one checkpoint would probe it once per phase instead of once per
// revision. Every other Repo method delegates straight through.
type revExistsMemoRepo struct {
	vcs.Repo
	mu     sync.Mutex
	cache  map[string]revExistsResult
	probes int
}

type revExistsResult struct {
	exists bool
	err    error
}

func (m *revExistsMemoRepo) RevisionExists(rev string) (bool, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if v, ok := m.cache[rev]; ok {
		return v.exists, v.err
	}
	m.probes++
	exists, err := m.Repo.RevisionExists(rev)
	if m.cache == nil {
		m.cache = map[string]revExistsResult{}
	}
	m.cache[rev] = revExistsResult{exists, err}
	return exists, err
}

// now is the render-time clock every date stamp in this file reads,
// exposed as a package-level variable so a test can advance it across a
// simulated day boundary without a real wall-clock wait — the only way to
// distinguish "reads a stable placeholder" from "reads the wall clock
// directly" within a single test process. Production code never assigns
// it.
var now = time.Now

// viewMarker identifies a generated view. Its presence is the renderer's
// permission to overwrite; its absence on an existing target is a refusal.
// The prefix is owned by internal/rules (the validator keys SDD163's
// projection exemption on it), so emission and recognition cannot drift.
func viewMarker(plan string) string {
	return fmt.Sprintf("%s%s-Graph.json. Regenerate with `sdd compile --plan %s`. Edits here are overwritten. -->", rules.GeneratedViewMarkerPrefix, plan, plan)
}

// graphViewBegin/End delimit the README's upserted section. Owned by
// internal/rules: lifecycle normalization strips exactly these delimiters,
// so a frozen phase review's README pin survives the upsert.
const (
	graphViewBegin = rules.GraphViewBegin
	graphViewEnd   = rules.GraphViewEnd
)

// phaseGroup is one rendered phase: its ordinal, label, and nodes in
// declaration order.
type phaseGroup struct {
	Ordinal int
	Label   string
	Title   string
	Doc     string
	Nodes   []*model.Node
}

// PhaseGroup is the exported projection of phaseGroup a caller needs to
// locate a rendered phase doc's owning nodes (`sdd phase complete` on a
// graph plan) without duplicating the grouping the renderer already does.
type PhaseGroup struct {
	Ordinal int
	Title   string
	Doc     string
	Nodes   []*model.Node
}

// GroupPhases is the exported form of groupPhases.
func GroupPhases(g *model.Graph, plan string) []PhaseGroup {
	groups := groupPhases(g, plan)
	out := make([]PhaseGroup, len(groups))
	for i, ph := range groups {
		out[i] = PhaseGroup{Ordinal: ph.Ordinal, Title: ph.Title, Doc: ph.Doc, Nodes: ph.Nodes}
	}
	return out
}

// groupPhases buckets nodes by their presentation label (DD-9: `phase` is a
// grouping consumed only by views), ordered by label with unlabeled nodes
// last as "Ungrouped".
func groupPhases(g *model.Graph, plan string) []phaseGroup {
	byLabel := map[string][]*model.Node{}
	var labels []string
	for i := range g.Nodes {
		n := &g.Nodes[i]
		if _, seen := byLabel[n.Phase]; !seen {
			labels = append(labels, n.Phase)
		}
		byLabel[n.Phase] = append(byLabel[n.Phase], n)
	}
	sort.SliceStable(labels, func(i, j int) bool {
		if (labels[i] == "") != (labels[j] == "") {
			return labels[j] == "" // unlabeled last
		}
		return labels[i] < labels[j]
	})
	var out []phaseGroup
	for i, label := range labels {
		title := label
		if title == "" {
			title = "Ungrouped"
		}
		ordinal := i + 1
		out = append(out, phaseGroup{
			Ordinal: ordinal,
			Label:   label,
			Title:   phaseTitle(title),
			Doc:     fmt.Sprintf("%02d-%s.md", ordinal, viewSlug(title)),
			Nodes:   byLabel[label],
		})
	}
	return out
}

var slugCleanRe = regexp.MustCompile(`[^A-Za-z0-9]+`)
var slugLeadingOrdinalRe = regexp.MustCompile(`^\d+-`)
var titleWordSplitRe = regexp.MustCompile(`[-_]+`)

// viewSlug turns a phase label into a filename component, dropping a leading
// `NN-` so a label like "01-core" does not double-number the doc.
func viewSlug(label string) string {
	s := slugLeadingOrdinalRe.ReplaceAllString(label, "")
	s = slugCleanRe.ReplaceAllString(s, "-")
	s = strings.Trim(s, "-")
	if s == "" {
		s = "phase"
	}
	return s
}

// phaseTitle derives a human title from a raw phase label: strips a leading
// numeric prefix (`01-hermetic-git` -> `hermetic-git`), splits on `-`/`_`,
// and title-cases each word. The label itself (and the doc file stem
// viewSlug derives from it) is untouched — only the rendered title changes,
// so regenerating an existing plan does not move files.
func phaseTitle(label string) string {
	s := slugLeadingOrdinalRe.ReplaceAllString(label, "")
	if s == "" {
		return label
	}
	words := titleWordSplitRe.Split(s, -1)
	var out []string
	for _, w := range words {
		if w == "" {
			continue
		}
		out = append(out, strings.ToUpper(w[:1])+strings.ToLower(w[1:]))
	}
	if len(out) == 0 {
		return label
	}
	return strings.Join(out, " ")
}

// phaseStatus projects a group's frontmatter status: `complete` only when
// every node is CLOSED (the derived D-0022 predicate — never a stored flag,
// never hand-checked), `in-progress` once any node carries a claim or
// observation, else `planned`.
func phaseStatus(nodes []*model.Node, closed map[string]bool) string {
	if allClosed(nodes, closed) {
		return "complete"
	}
	for _, n := range nodes {
		if n.Claim != nil || n.Verification != nil {
			return "in-progress"
		}
	}
	return "planned"
}

// allClosed reports whether every node in the group derives closed.
func allClosed(nodes []*model.Node, closed map[string]bool) bool {
	if len(nodes) == 0 {
		return false
	}
	for _, n := range nodes {
		if !closed[n.ID] {
			return false
		}
	}
	return true
}

// renderPhaseDoc produces one phase view. created/updated are supplied by
// the writer so unchanged content stays byte-identical across days. st and
// closed carry the derived truth the view projects (DD-2: a projection may
// show derived state precisely because it is never parsed back).
func renderPhaseDoc(planDir, plan string, g *model.Graph, ph phaseGroup, created, updated, repoRoot string, repo vcs.Repo, st map[string]states.NodeState, closed map[string]bool) (string, error) {
	frozen := allClosed(ph.Nodes, closed)
	var b strings.Builder
	fmt.Fprintf(&b, "---\ntitle: \"%s\"\ntype: phase\nplan: \"%s\"\nphase: %d\nstatus: %s\n", ph.Title, plan, ph.Ordinal, phaseStatus(ph.Nodes, closed))
	fmt.Fprintf(&b, "created: %s\nupdated: %s\n", created, updated)
	fmt.Fprintf(&b, "deliverable: \"Graph view: %d node(s) under phase label %s\"\ntasks: []\n---\n\n", len(ph.Nodes), ph.Title)
	fmt.Fprintf(&b, "# Phase %d: %s\n\n%s\n\n", ph.Ordinal, ph.Title, viewMarker(plan))
	if frozen {
		fmt.Fprintf(&b, "%s\n\n", frozenViewMarker)
	}

	b.WriteString("## Overview\n\n")
	fmt.Fprintf(&b, "Rendered view of %d node(s) from the plan graph (schema v%d, seq %d).\n", len(ph.Nodes), g.Version, g.SeqCounter)
	b.WriteString("Observations shown are raw records; completion-grade closure derives from\nfull review gates and is never stored or hand-edited here.\n\n")

	b.WriteString("## Nodes\n")
	for _, n := range ph.Nodes {
		fmt.Fprintf(&b, "\n### %s\n\n", n.ID)
		fmt.Fprintf(&b, "- Contract: %s\n", n.Contract)
		fmt.Fprintf(&b, "- Justifies: %s\n", joinOr(n.Justifies, "(nothing — will not compile)"))
		fmt.Fprintf(&b, "- Depends on: %s\n", joinOr(n.Deps, "(nothing)"))
		fmt.Fprintf(&b, "- Gate: %s\n", describeGate(n.Gate))
		fmt.Fprintf(&b, "- Hazards: %s\n", describeHazards(n.Hazards))
		if len(n.Artifacts) > 0 {
			fmt.Fprintf(&b, "- Artifacts: %s\n", strings.Join(n.Artifacts, ", "))
		}
		if len(n.Inputs) > 0 {
			fmt.Fprintf(&b, "- Inputs: %s\n", describeInputs(n.Inputs))
		}
		fmt.Fprintf(&b, "- Estimate: %d\n", n.Estimate)
		if n.History != "" {
			fmt.Fprintf(&b, "- History: %s\n", n.History)
		}
		fmt.Fprintf(&b, "- Observation: %s\n", describeObservation(n.Verification))
		fmt.Fprintf(&b, "- Closure: %s\n", describeClosure(n.ID, st, closed))
		if n.Claim != nil {
			fmt.Fprintf(&b, "- Claim: %s (lease expires %s)\n", n.Claim.By, n.Claim.LeaseExpires)
		}
	}

	b.WriteString("\n## Acceptance Criteria\n\n")
	box := "[ ]"
	if frozen {
		box = "[x]"
	}
	fmt.Fprintf(&b, "- %s Every node in this phase is truly closed: a passing observation, and\n      coverage by a passing frozen full review gate (derived from the graph;\n      never checked off by hand).\n\n", box)
	if frozen {
		before, after, err := renderPhaseEvidenceHalves(planDir, plan, ph, repoRoot, "{VERIFIED_DATE}")
		if err != nil {
			return "", err
		}
		// Skip the identity probe entirely when this render would be a
		// byte-identical no-op: compare everything EXCEPT the identity-
		// recheck line itself (the only piece a probe produces) against the
		// existing on-disk frozen view with ITS OWN identity-recheck line
		// similarly excised. Only when nothing else would change is the
		// existing line reused verbatim instead of re-probing revision
		// existence; any other difference (a node field, a review now
		// covering the phase, ...) still falls through to a real probe, so
		// the frozen-view refusal for a genuine change is never masked
		// (review-execution ef1962e F-01 item 4).
		// A nil repo never reaches identityRecheckLine's real probe branch
		// (it renders "no recheck ran" unconditionally) — there is nothing
		// to memoize, and reusing a stale existing line here would mask a
		// resolution regression as a no-op instead of letting planWrite's
		// frozen-view comparison see and refuse it (item 7).
		if existing, rerr := os.ReadFile(filepath.Join(planDir, ph.Doc)); rerr == nil && repo != nil {
			if existingCore, existingBody, found := stripPhaseEvidenceSection(string(existing)); found &&
				strings.Contains(string(existing), frozenViewMarker) &&
				strings.TrimSpace(existingBody) != "Pending — not complete." {
				if loc := identityRecheckLineRe.FindStringIndex(existingBody); loc != nil {
					existingLine := existingBody[loc[0]:loc[1]]
					existingBefore := existingBody[:loc[0]]
					existingAfter := existingBody[loc[1]:]
					normalizeCore := func(s string) string {
						return createdLineRe.ReplaceAllString(updatedLineRe.ReplaceAllString(s, "updated: {DATE}"), "created: {DATE}")
					}
					normalizeBefore := func(s string) string {
						return verifiedLineRe.ReplaceAllString(s, "- Verified: {VERIFIED_DATE}")
					}
					wantCore := strings.TrimRight(b.String(), "\n")
					if normalizeCore(wantCore) == normalizeCore(existingCore) &&
						normalizeBefore(before) == normalizeBefore(existingBefore) &&
						strings.TrimRight(after, "\n") == strings.TrimRight(existingAfter, "\n") {
						b.WriteString("## Phase Completion Evidence\n\n")
						b.WriteString(existingBefore)
						b.WriteString(existingLine)
						b.WriteString(existingAfter)
						b.WriteByte('\n')
						return b.String(), nil
					}
				}
			}
		}
		b.WriteString("## Phase Completion Evidence\n\n")
		rev := phaseCheckpoint(ph.Nodes)
		line, err := identityRecheckLine(repo, rev, "{VERIFIED_DATE}")
		if err != nil {
			return "", err
		}
		b.WriteString(strings.TrimRight(before+line+after, "\n") + "\n")
	} else {
		b.WriteString("## Phase Completion Evidence\n\n")
		b.WriteString("Pending — not complete.\n")
	}
	return b.String(), nil
}

// describeClosure projects the two-axis closure distinction (D-0022):
// closed vs assumed-closed for GREEN nodes, the derived state otherwise.
// A nil st/closed (a caller without derive inputs) reads as the zero state.
func describeClosure(id string, st map[string]states.NodeState, closed map[string]bool) string {
	switch {
	case closed[id]:
		return "**closed** — GREEN and covered by a passing frozen full review gate"
	case st[id].State == states.Green:
		return "assumed-closed — GREEN, not yet covered by a passing full review gate (sufficient to build on, not completion-grade)"
	case st[id].State == "":
		return "underived (no state inputs at render time)"
	default:
		return fmt.Sprintf("open — state %s", st[id].State)
	}
}

func joinOr(values []string, empty string) string {
	if len(values) == 0 {
		return empty
	}
	quoted := make([]string, len(values))
	for i, v := range values {
		quoted[i] = "`" + v + "`"
	}
	return strings.Join(quoted, ", ")
}

func describeGate(gate model.Gate) string {
	switch gate.Type {
	case model.GateTests:
		if len(gate.Tests) == 0 {
			return "tests (none named yet)"
		}
		var parts []string
		for _, t := range gate.Tests {
			s := fmt.Sprintf("`%s` in %s", t.ID, t.File)
			if len(t.Satisfies) > 0 {
				s += fmt.Sprintf(" (satisfies %s)", strings.Join(t.Satisfies, ", "))
			}
			parts = append(parts, s)
		}
		return "tests — " + strings.Join(parts, "; ")
	case model.GateCommand:
		return fmt.Sprintf("command — `%s`", gate.Command)
	case model.GateReview:
		if gate.Lanes == nil {
			return "review — full (carries completion-grade closure)"
		}
		return "review — lanes: " + strings.Join(gate.Lanes, ", ")
	case model.GateUnspecified:
		return "UNSPECIFIED (conversion sentinel; blocks compile until an operator states how this node is verified)"
	default:
		return gate.Type
	}
}

func describeHazards(h model.Hazards) string {
	switch {
	case h == nil:
		return "UNTRIAGED (blocks compile until resolved)"
	case len(h) == 0:
		return "none (explicit claim)"
	default:
		return strings.Join(h, ", ")
	}
}

// describeInputs renders a node's declared read-only inputs for views:
// `root:path` (whole file) or `root:path#Heading / Path` (section).
func describeInputs(inputs []model.Input) string {
	parts := make([]string, len(inputs))
	for i, in := range inputs {
		parts[i] = "`" + describeInputSpec(in) + "`"
	}
	return strings.Join(parts, ", ")
}

func describeObservation(v *model.Verification) string {
	if v == nil {
		return "none yet"
	}
	s := fmt.Sprintf("**%s** at seq %d — isolation %s", v.Result, v.Seq, v.Isolation)
	if v.Provenance != nil {
		p := v.Provenance.Kind
		if v.Provenance.Revision != "" {
			p += " " + shortRev(v.Provenance.Revision)
		}
		if v.Provenance.Changelist != "" {
			p += " CL " + v.Provenance.Changelist
		}
		s += ", provenance " + p
	}
	return s
}

func shortRev(rev string) string {
	if len(rev) > 12 {
		return rev[:12]
	}
	return rev
}

var (
	createdLineRe = regexp.MustCompile(`(?m)^created: (\S+)`)
	updatedLineRe = regexp.MustCompile(`(?m)^updated: (\S+)`)
	// planEvidenceHeadingRe locates the evidence section the graph-view
	// insertion must stay ahead of.
	planEvidenceHeadingRe = regexp.MustCompile(`(?m)^## Plan Completion Evidence\s*$`)
	// identityRecheckLineRe matches the single `- Identity recheck: ...`
	// line (plus its trailing blank line) identityRecheckLine renders —
	// the only piece of a phase's evidence body a real repository probe
	// produces. renderPhaseDoc's no-op short-circuit excises exactly this
	// span from both the wanted and existing evidence bodies before
	// deciding whether the probe can be skipped.
	identityRecheckLineRe = regexp.MustCompile(`(?m)^- Identity recheck:.*\n\n`)
	// verifiedLineRe matches evidence's `- Verified: DATE` line, filled
	// with the SAME `updated` stamp fillDates uses — normalizing it
	// alongside created/updated lets renderPhaseDoc's no-op short-circuit
	// compare a freshly rendered ({VERIFIED_DATE}-templated) evidence body
	// against the existing on-disk (already date-filled) one.
	verifiedLineRe = regexp.MustCompile(`(?m)^- Verified: (\S+)`)
	// legacyGraphViewHeadingRe recognizes an orphaned `## Graph View`
	// section left by a render that predates the begin marker: legacyGraphViewSpan
	// uses it to find and replace the whole legacy span instead of
	// upserting a second section alongside it.
	legacyGraphViewHeadingRe = regexp.MustCompile(`(?m)^## Graph View\s*$`)
)

// legacyGraphViewSpan locates an orphaned `## Graph View` section that
// carries no `graph-view:begin` marker (planReadmeUpdate's caller has
// already confirmed graphViewBegin is absent) — the shape a render from
// before the begin marker existed leaves behind: a `## Graph View` heading,
// optionally followed later by a `graph-view:end` marker. found is false
// when no such heading exists at all (a genuinely first render). When the
// heading is found but no end marker follows it, the span extends to the
// next depth<=2 heading (or EOF) exactly like nextH2HeadingRe's other
// callers — the heading's own natural section extent.
func legacyGraphViewSpan(src string) (start, end int, found bool) {
	loc := legacyGraphViewHeadingRe.FindStringIndex(src)
	if loc == nil {
		return 0, 0, false
	}
	start = loc[0]
	if endLoc := strings.Index(src[loc[1]:], graphViewEnd); endLoc >= 0 {
		return start, loc[1] + endLoc + len(graphViewEnd), true
	}
	if rest := nextH2HeadingRe.FindStringIndex(src[loc[1]:]); rest != nil {
		return start, loc[1] + rest[0], true
	}
	return start, len(src), true
}

// planWrite decides one view target's fate without writing: whether a write
// is needed, and the exact bytes to write. It carries BOTH refusal rules —
// an existing non-generated file (hand-authored or frozen v1 history), and
// an existing FROZEN VIEW whose content would change (DD-2: a projection of
// closed work is history; byte-identical re-renders stay no-ops). Shared by
// preflight (dry-run, before the graph write) and writeView, so a refusal
// can never fire after the graph moved.
func planWrite(path, content, plan string) (write bool, filled string, err error) {
	today := now().Format("2006-01-02")
	existing, readErr := os.ReadFile(path)
	if readErr != nil {
		if !os.IsNotExist(readErr) {
			return false, "", readErr
		}
		return true, fillDates(content, today, today), nil
	}
	if !strings.Contains(string(existing), viewMarker(plan)) {
		return false, "", fmt.Errorf("compile: %s exists and is not a generated view; refusing to overwrite it (a hand-authored or frozen document is taken over by `sdd graph convert`, never clobbered by a render)", path)
	}
	created := today
	if m := createdLineRe.FindStringSubmatch(string(existing)); m != nil {
		created = m[1]
	}
	prevUpdated := today
	if m := updatedLineRe.FindStringSubmatch(string(existing)); m != nil {
		prevUpdated = m[1]
	}
	// Byte-stability check: same content under the existing stamps means no
	// write at all — and therefore no frozen-view refusal either, so
	// compile stays runnable on a completed plan.
	if fillDates(content, created, prevUpdated) == string(existing) {
		return false, "", nil
	}
	if strings.Contains(string(existing), frozenViewMarker) {
		// The frozen-view invariant is about REOPENING, not about byte
		// drift: refuse only when the projected history itself would
		// change — the graph's closure regressed (no longer frozen-shaped)
		// or a node's own projected content (contract, gate, observation,
		// closure, ...) differs. A renderer upgrade that only ADDS to the
		// derived `## Phase Completion Evidence` section (e.g. this
		// completion-evidence rendering itself) changes none of that: the
		// projection of history is unchanged, only the renderer's ability
		// to state it is. Comparing both renderings with their evidence
		// sections stripped isolates exactly that distinction, so compile
		// stays able to pick up a renderer fix on an already-completed
		// plan without ever silently rewriting what the projection says
		// happened.
		existingCore, existingEvidenceBody, existingHasEvidence := stripPhaseEvidenceSection(string(existing))
		contentCore, contentEvidenceBody, contentHasEvidence := stripPhaseEvidenceSection(content)
		refuse := !contentHasEvidence || !existingHasEvidence ||
			fillDates(contentCore, created, prevUpdated) != existingCore
		if !refuse {
			// The projection of history (everything before the evidence
			// section) is unchanged. A renderer upgrade may only ADD
			// evidence (placeholder "Pending — not complete." ->
			// populated body); once both the frozen view and the new
			// rendering already carry a populated (non-placeholder) body,
			// a differing body is a change like any other frozen change
			// and must be refused too (review-execution 56815db-b F-01
			// item 4).
			existingPending := strings.TrimSpace(existingEvidenceBody) == "Pending — not complete."
			filledContentBody := fillDates(contentEvidenceBody, created, prevUpdated)
			if !existingPending && filledContentBody != existingEvidenceBody {
				refuse = true
				// When the ONLY difference is the identity-recheck line
				// regressing from a real probe result to "no recheck ran",
				// the cause is a repository that no longer resolves at
				// render time — name that as the cause instead of the
				// generic reopened-phase message, while still refusing
				// (review-execution ef1962e F-01 item 7).
				if noRecheckRegression(existingEvidenceBody, filledContentBody) {
					return false, "", fmt.Errorf("compile: %s is a frozen view, and this render could not confirm the recorded revision still exists — no target repository resolved at render time, so its Identity recheck line would regress from a real probe result to \"no recheck ran\"; resolve the target repository (or delete the frozen view file explicitly and recompile if the phase was legitimately reopened) and try again", path)
				}
			}
		}
		if refuse {
			return false, "", fmt.Errorf("compile: %s is a frozen view — every node in it was closed when it was rendered, and the graph now disagrees with that frozen history; if the phase was legitimately reopened (a review finding demoted a node), delete the frozen view file explicitly and recompile", path)
		}
	}
	return true, fillDates(content, created, today), nil
}

// noRecheckRegression reports whether existingBody and newBody differ ONLY
// in their `- Identity recheck:` line, with the new line specifically
// regressing to "no recheck ran" (no resolved target repository at render
// time) from an existing line that reported a real probe outcome — the one
// frozen-view refusal shape whose cause is a missing repository resolution,
// not a genuine change to the projected history.
func noRecheckRegression(existingBody, newBody string) bool {
	newLoc := identityRecheckLineRe.FindStringIndex(newBody)
	if newLoc == nil || !strings.Contains(newBody[newLoc[0]:newLoc[1]], "no recheck ran") {
		return false
	}
	existingLoc := identityRecheckLineRe.FindStringIndex(existingBody)
	if existingLoc == nil || strings.Contains(existingBody[existingLoc[0]:existingLoc[1]], "no recheck ran") {
		return false
	}
	strippedExisting := existingBody[:existingLoc[0]] + existingBody[existingLoc[1]:]
	strippedNew := newBody[:newLoc[0]] + newBody[newLoc[1]:]
	return strippedExisting == strippedNew
}

// phaseEvidenceHeadingRe locates a phase doc's `## Phase Completion
// Evidence` section — always the view's last section (renderPhaseDoc emits
// nothing after it), so everything from the heading to EOF is exactly that
// section's extent. A node's own Contract text is rendered verbatim earlier
// in the document (the `## Nodes` section) and could itself contain a line
// that matches this heading shape; stripPhaseEvidenceSection anchors on the
// LAST match rather than the first for exactly that reason — the renderer's
// own section is always the final occurrence, a boundary the writer
// controls, never the content a node happens to carry (review-execution
// 56815db-b F-01 item 4).
var phaseEvidenceHeadingRe = regexp.MustCompile(`(?m)^## Phase Completion Evidence\s*$`)

// stripPhaseEvidenceSection returns a rendered phase doc with its `## Phase
// Completion Evidence` section (heading and body) removed, the section's
// own body (trimmed), and whether the heading was found. Used only to
// isolate frozen-view byte comparison from evidence-only content growth
// (planWrite) — never to change what is written.
func stripPhaseEvidenceSection(content string) (core, body string, found bool) {
	locs := phaseEvidenceHeadingRe.FindAllStringIndex(content, -1)
	if len(locs) == 0 {
		return content, "", false
	}
	loc := locs[len(locs)-1]
	core = strings.TrimRight(content[:loc[0]], "\n")
	body = strings.TrimSpace(content[loc[1]:])
	return core, body, true
}

// writeView writes one rendered view with date stability: an existing
// generated view keeps its created date, and keeps its bytes entirely when
// nothing but the updated stamp would change.
func writeView(path, content, plan string) (wrote bool, err error) {
	write, filled, err := planWrite(path, content, plan)
	if err != nil || !write {
		return false, err
	}
	return true, istore.WriteAtomic(path, filled)
}

// fillDates substitutes the renderer's date placeholders: the frontmatter
// `created:`/`updated:` stamps (count=1 each — exactly one frontmatter
// line), and every `{VERIFIED_DATE}` placeholder (count=all) WITHIN the `##
// Phase Completion Evidence` section only — never document-wide, because a
// node's own Contract text (rendered verbatim in `## Nodes`, earlier in the
// document) could legitimately contain that literal string and must survive
// unchanged (review-execution ef1962e F-01 item 3). Reusing the same
// `updated` value as the evidence date means a byte-identical re-render
// (nothing else changed) still stamps `updated` exactly once and stays
// stable — the evidence date does not independently drift across days the
// way a live time.Now() read at evidence-render time would (which would
// defeat frozen-view byte-stability: a frozen view could never be
// re-rendered as a no-op once a day passed).
func fillDates(content, created, updated string) string {
	content = strings.Replace(content, "created: {DATE}", "created: "+created, 1)
	content = strings.Replace(content, "updated: {DATE}", "updated: "+updated, 1)
	core, body, found := stripPhaseEvidenceSection(content)
	if !found {
		// No `## Phase Completion Evidence` heading in content: either a
		// bare evidence-body fragment a caller (planWrite's frozen-view
		// comparison) is filling in isolation — never the whole document,
		// so there is no Contract text this replace could clobber — or a
		// document that genuinely carries no evidence section at all.
		// Either way an unconditional replace is exactly right here.
		return strings.ReplaceAll(content, "{VERIFIED_DATE}", updated)
	}
	filledBody := strings.ReplaceAll(body, "{VERIFIED_DATE}", updated)
	return core + "\n\n## Phase Completion Evidence\n\n" + filledBody + "\n"
}

// preflightViews dry-runs every render target before anything is written:
// both refusal rules (non-generated file in a target's place, frozen view
// whose content would change) fire here, BEFORE the graph write, leaving
// nothing half-done. repo is the caller's already-resolved evidence repo
// (shared with the write pass so an identity probe memoized here is not
// repeated there).
func preflightViews(root, plan, repoRoot string, repo vcs.Repo, g *model.Graph, st map[string]states.NodeState, closed map[string]bool) error {
	planDir := filepath.Join(root, "Plans", plan)
	for _, ph := range groupPhases(g, plan) {
		path := filepath.Join(planDir, ph.Doc)
		content, err := renderPhaseDoc(planDir, plan, g, ph, "{DATE}", "{DATE}", repoRoot, repo, st, closed)
		if err != nil {
			return err
		}
		if _, _, err := planWrite(path, content, plan); err != nil {
			return err
		}
	}
	_, _, err := planReadmeUpdate(planDir, plan, groupPhases(g, plan), closed)
	return err
}

// resolveEvidenceRepo resolves the vcs.Repo the phase evidence's identity
// recheck probes, or nil when repoRoot is empty (no resolved target
// repository at render time) or repoRoot is under no supported VCS — the
// honest "no recheck ran" case identityRecheckLine renders rather than
// fabricating a check. A detection failure that IS operational (the git
// executable itself unavailable, ...) still resolves to vcs.Unavailable,
// which correctly reports vcs.ErrOperational once actually probed. The
// returned repo memoizes RevisionExists per revision for the lifetime of
// this Repo value — callers that render more than once (preflight, then
// write) must resolve it ONCE and share the result so the memo covers both
// passes.
func resolveEvidenceRepo(repoRoot string) vcs.Repo {
	if repoRoot == "" {
		return nil
	}
	repo := vcs.Detect(repoRoot)
	if repo.Kind() == vcs.None {
		return nil
	}
	return &revExistsMemoRepo{Repo: repo}
}

// RenderViews writes the phase views and updates the README projection.
// Exported so callers outside a staged-proposal compile (e.g. `sdd plan
// complete` / `sdd phase complete` on a graph plan, which have nothing to
// stage) can refresh the same rendered views `sdd compile` produces,
// without duplicating the renderer. repoRoot is the resolved target
// repository, used only to derive the Repository label the plan/phase
// completion evidence sections carry (SDD072).
func RenderViews(root, plan, repoRoot string, g *model.Graph, st map[string]states.NodeState, closed map[string]bool) ([]string, error) {
	return renderViews(root, plan, repoRoot, g, st, closed)
}

// renderViews writes the phase views and updates the README projection.
func renderViews(root, plan, repoRoot string, g *model.Graph, st map[string]states.NodeState, closed map[string]bool) ([]string, error) {
	planDir := filepath.Join(root, "Plans", plan)
	groups := groupPhases(g, plan)
	// Resolved ONCE and shared with the write pass below, so a revision's
	// identity probe (renderPhaseEvidence -> identityRecheckLine) is
	// memoized across both passes rather than run twice per closed phase.
	repo := resolveEvidenceRepo(repoRoot)
	if err := preflightViews(root, plan, repoRoot, repo, g, st, closed); err != nil {
		return nil, err
	}

	// Phase files are written FIRST: planReadmeUpdate's status/title
	// reconciliation (refreshReadmePhaseStatuses) reads each phase doc from
	// disk to confirm it carries the generated-view marker before touching
	// its README entry — ownership it can only ever see once the doc
	// exists. Reading the README before this loop (and writing it after,
	// compare-and-swap against that read) still keeps a just-created
	// marker from retroactively authorizing a takeover of an existing
	// hand-authored entry: writeView's own frozen/marker refusals gate
	// each phase file independently, before any of them lands.
	var written []string
	for _, ph := range groups {
		path := filepath.Join(planDir, ph.Doc)
		// Dates stay templated here; writeView fills them with stability
		// rules (existing created preserved, updated stamped on change).
		content, err := renderPhaseDoc(planDir, plan, g, ph, "{DATE}", "{DATE}", repoRoot, repo, st, closed)
		if err != nil {
			return nil, err
		}
		wrote, err := writeView(path, content, plan)
		if err != nil {
			return nil, err
		}
		if wrote {
			written = append(written, path)
		}
	}

	readmeBefore, err := os.ReadFile(filepath.Join(planDir, "README.md"))
	if err != nil {
		return nil, err
	}
	readme, readmeChanged, err := planReadmeUpdate(planDir, plan, groups, closed)
	if err != nil {
		return nil, err
	}

	if readmeChanged {
		if err := istore.WriteAtomicExpecting(filepath.Join(planDir, "README.md"), readme, istore.Digest(string(readmeBefore))); err != nil {
			return nil, err
		}
		written = append(written, filepath.Join(planDir, "README.md"))
	}
	return written, nil
}

// updateReadme applies the preflightable, surgical README projection.
func updateReadme(planDir, plan string, groups []phaseGroup, closed map[string]bool) (bool, error) {
	before, err := os.ReadFile(filepath.Join(planDir, "README.md"))
	if err != nil {
		return false, err
	}
	out, changed, err := planReadmeUpdate(planDir, plan, groups, closed)
	if err != nil || !changed {
		return false, err
	}
	return true, istore.WriteAtomicExpecting(filepath.Join(planDir, "README.md"), out, istore.Digest(string(before)))
}

func planReadmeUpdate(planDir, plan string, groups []phaseGroup, closed map[string]bool) (string, bool, error) {
	path := filepath.Join(planDir, "README.md")
	raw, err := os.ReadFile(path)
	if err != nil {
		return "", false, fmt.Errorf("compile: reading plan README: %w", err)
	}
	src := string(raw)
	out := src

	out, err = refreshReadmePhaseStatuses(planDir, plan, out, groups, closed)
	if err != nil {
		return "", false, err
	}

	section := renderGraphViewSection(plan, groups)
	if begin := strings.Index(out, graphViewBegin); begin >= 0 {
		end := strings.Index(out, graphViewEnd)
		if end < begin {
			return "", false, fmt.Errorf("compile: %s has a malformed graph-view section (begin without end)", path)
		}
		out = out[:begin] + section + out[end+len(graphViewEnd):]
	} else if legacyBegin, legacyEnd, found := legacyGraphViewSpan(out); found {
		// A pre-begin-marker render left an orphaned `## Graph View`
		// section: a heading (optionally followed by `graph-view:end`, the
		// only marker that predates the begin marker) with no matching
		// begin. Upserting without recognizing this span would insert a
		// SECOND section, leaving the document with one begin marker but
		// two end markers — the next render's begin-anchored search then
		// pairs the new begin with the OLD orphaned end (whichever comes
		// first), reporting "begin without end". Replacing the whole
		// legacy span in place is what upsert would have done had the
		// begin marker always been there.
		out = out[:legacyBegin] + section + out[legacyEnd:]
	} else if i := planEvidenceHeadingRe.FindStringIndex(out); i != nil {
		// Insert BEFORE the Plan Completion Evidence section, never after:
		// evidence writers replace that section's whole extent (up to the
		// next depth<=2 heading), and the begin marker is a comment, not a
		// heading — a section appended after the evidence heading gets its
		// begin marker swallowed by the next evidence write, orphaning the
		// projection from the lifecycle strip that keeps frozen review
		// pins honest.
		out = out[:i[0]] + section + "\n\n" + out[i[0]:]
	} else {
		if !strings.HasSuffix(out, "\n") {
			out += "\n"
		}
		out += "\n" + section + "\n"
	}

	// The plan evidence's Verified date is rendered as the same
	// {VERIFIED_DATE} placeholder the phase docs use, then filled with
	// whatever `updated` stamp this render settles on below — never the
	// render-time clock directly. That is what makes an unchanged closed
	// plan's Verified line, and therefore its whole evidence body, stay
	// byte-identical across days: the placeholder participates in the
	// byte-stability comparison the same way the rest of the projection
	// does (review-execution 56815db-b F-01 item 5).
	out, err = applyPlanEvidence(planDir, plan, out, groups, closed, "{VERIFIED_DATE}")
	if err != nil {
		return "", false, err
	}

	prevUpdated := now().Format("2006-01-02")
	if m := updatedLineRe.FindStringSubmatch(src); m != nil {
		prevUpdated = m[1]
	}
	// Byte-stability check: filling the {VERIFIED_DATE} placeholder — WITHIN
	// the `## Plan Completion Evidence` section only, never document-wide,
	// because the plan's own free text could legitimately contain that
	// literal string (review-execution ef1962e F-01 item 3) — with the
	// PREVIOUS updated stamp and comparing against src tells whether
	// anything besides the date actually changed — the same shape the
	// phase docs' planWrite performs.
	if fillPlanEvidenceDate(out, prevUpdated) == src {
		return "", false, nil
	}
	// A real change restamps the README's updated date (both the
	// frontmatter field and every {VERIFIED_DATE} placeholder the evidence
	// body carries) to today; an unchanged README is never touched, so
	// idempotent re-renders stay byte-stable.
	today := now().Format("2006-01-02")
	out = fillPlanEvidenceDate(out, today)
	end, err := readmeFrontmatterEnd(out)
	if err != nil {
		return "", false, err
	}
	out = updatedLineRe.ReplaceAllString(out[:end], "updated: "+today) + out[end:]
	return out, true, nil
}

// nextH2HeadingRe finds the next depth<=2 heading, the extent every
// evidence writer (this one included) replaces up to (SDD020's duplicate
// check: exactly one visible `## Plan Completion Evidence` section).
var nextH2HeadingRe = regexp.MustCompile(`(?m)^ {0,3}#{1,2}\s+`)

// fillPlanEvidenceDate substitutes every `{VERIFIED_DATE}` placeholder
// WITHIN the `## Plan Completion Evidence` section body only — the same
// extent applyPlanEvidence writes to (heading to the next depth<=2 heading
// or EOF) — never document-wide, because the plan's own free text (outside
// the generated sections) could legitimately contain that literal string
// (review-execution ef1962e F-01 item 3). A README with no such section is
// returned unchanged.
func fillPlanEvidenceDate(src, date string) string {
	loc := planEvidenceHeadingRe.FindStringIndex(src)
	if loc == nil {
		return src
	}
	bodyStart := loc[1]
	for bodyStart < len(src) && src[bodyStart] == '\n' {
		bodyStart++
	}
	bodyEnd := len(src)
	if rest := nextH2HeadingRe.FindStringIndex(src[bodyStart:]); rest != nil {
		bodyEnd = bodyStart + rest[0]
	}
	filled := strings.ReplaceAll(src[bodyStart:bodyEnd], "{VERIFIED_DATE}", date)
	return src[:bodyStart] + filled + src[bodyEnd:]
}

// applyPlanEvidence replaces the `## Plan Completion Evidence` section body
// with the derived evidence once every phase in groups is closed and every
// completed phase resolves a covering final review (renderPlanEvidence);
// otherwise the section (typically still `Pending — not complete.`) is left
// exactly as it is — this function never invents evidence and never
// regresses a section a human or an earlier render already completed.
func applyPlanEvidence(planDir, plan, src string, groups []phaseGroup, closed map[string]bool, verifiedDate string) (string, error) {
	body, ok, err := renderPlanEvidence(planDir, plan, verifiedDate, groups, closed)
	if err != nil {
		return "", err
	}
	if !ok {
		return src, nil
	}
	loc := planEvidenceHeadingRe.FindStringIndex(src)
	if loc == nil {
		return src, nil
	}
	bodyStart := loc[1]
	for bodyStart < len(src) && src[bodyStart] == '\n' {
		bodyStart++
	}
	rest := nextH2HeadingRe.FindStringIndex(src[bodyStart:])
	bodyEnd := len(src)
	if rest != nil {
		bodyEnd = bodyStart + rest[0]
	}
	return src[:bodyStart] + body + "\n" + src[bodyEnd:], nil
}

func readmeFrontmatterEnd(src string) (int, error) {
	if !strings.HasPrefix(src, "---\n") {
		return 0, fmt.Errorf("compile: README requires YAML frontmatter")
	}
	at := strings.Index(src[4:], "\n---\n")
	if at < 0 {
		return 0, fmt.Errorf("compile: README frontmatter is not closed")
	}
	return 4 + at + 1, nil // beginning of the closing delimiter
}

// refreshReadmePhaseStatuses changes only the owned scalar tokens. YAML node
// positions keep comments, quoting, extra fields, flow style and identity prose
// intact instead of serializing the entire frontmatter through a flat model.
func refreshReadmePhaseStatuses(planDir, plan, src string, groups []phaseGroup, closed map[string]bool) (string, error) {
	end, err := readmeFrontmatterEnd(src)
	if err != nil {
		return "", err
	}
	fm := src[4:end]
	var doc yaml.Node
	if err := yaml.Unmarshal([]byte(fm), &doc); err != nil {
		return "", fmt.Errorf("compile: invalid README YAML: %w", err)
	}
	if len(doc.Content) != 1 || doc.Content[0].Kind != yaml.MappingNode {
		return "", fmt.Errorf("compile: README frontmatter must be a mapping")
	}
	var phases, key *yaml.Node
	for i := 0; i < len(doc.Content[0].Content); i += 2 {
		if doc.Content[0].Content[i].Value == "phases" {
			if phases != nil {
				return "", fmt.Errorf("compile: duplicate README phases field")
			}
			key, phases = doc.Content[0].Content[i], doc.Content[0].Content[i+1]
		}
	}
	if phases == nil {
		return src, nil
	}
	if phases.Kind != yaml.SequenceNode {
		return "", fmt.Errorf("compile: README phases must be a sequence")
	}
	offset := func(n *yaml.Node) (int, error) {
		at := 4
		for line := 1; line < n.Line; line++ {
			next := strings.IndexByte(src[at:end], '\n')
			if next < 0 {
				return 0, fmt.Errorf("compile: invalid phase source position")
			}
			at += next + 1
		}
		// YAML columns count Unicode code points, not bytes.
		for column := 1; column < n.Column; column++ {
			if at >= end {
				return 0, fmt.Errorf("compile: invalid phase source column")
			}
			_, size := utf8.DecodeRuneInString(src[at:end])
			at += size
		}
		return at, nil
	}
	if len(phases.Content) == 0 && len(groups) > 0 {
		start, err := offset(key)
		if err != nil {
			return "", err
		}
		value, err := offset(phases)
		if err != nil {
			return "", err
		}
		lineEnd := strings.IndexByte(src[value:end], '\n')
		if lineEnd < 0 {
			return "", fmt.Errorf("compile: unsupported empty phases layout")
		}
		lineEnd += value
		close := strings.IndexByte(src[value:lineEnd], ']')
		if close < 0 || src[value] != '[' || strings.TrimSpace(src[value+1:value+close]) != "" {
			return "", fmt.Errorf("compile: empty phases must use [] on one line")
		}
		close += value
		var b strings.Builder
		b.WriteString(strings.TrimRight(src[start:value], " \t"))
		b.WriteString(src[close+1 : lineEnd])
		b.WriteByte('\n')
		for _, ph := range groups {
			fmt.Fprintf(&b, "  - id: %d\n    title: %s\n    status: %s\n    doc: %s\n", ph.Ordinal, strconv.Quote(ph.Title), phaseStatus(ph.Nodes, closed), strconv.Quote(ph.Doc))
		}
		return src[:start] + b.String() + src[lineEnd+1:], nil
	}
	type edit struct {
		start, end int
		text       string
	}
	var edits []edit
	for _, entry := range phases.Content {
		if entry.Kind != yaml.MappingNode {
			continue
		}
		fields := map[string]*yaml.Node{}
		for i := 0; i < len(entry.Content); i += 2 {
			k := entry.Content[i].Value
			if fields[k] != nil {
				return "", fmt.Errorf("compile: duplicate phase field %q", k)
			}
			fields[k] = entry.Content[i+1]
		}
		if fields["id"] == nil || fields["doc"] == nil {
			continue
		}
		for _, ph := range groups {
			if fields["doc"].Value != ph.Doc {
				continue
			}
			old, err := os.ReadFile(filepath.Join(planDir, ph.Doc))
			if os.IsNotExist(err) {
				continue
			}
			if err != nil {
				return "", err
			}
			if !strings.Contains(string(old), viewMarker(plan)) {
				continue
			}
			if fields["id"].Value != strconv.Itoa(ph.Ordinal) {
				return "", fmt.Errorf("compile: generated phase %s has README id %q, expected %d; reconcile the identity instead of silently leaving a stale status", ph.Doc, fields["id"].Value, ph.Ordinal)
			}
			statusEdit, err := scalarFieldEdit(src, end, offset, fields["status"], phaseStatus(ph.Nodes, closed), "status", ph.Doc)
			if err != nil {
				return "", err
			}
			if statusEdit != nil {
				edits = append(edits, *statusEdit)
			}
			// SDD152: the README phase entry's title and the phase doc's own
			// `title` frontmatter must agree exactly. The doc's title is the
			// human-derived one (phaseTitle); this keeps the README entry in
			// sync with it the same way status is kept in sync, rather than
			// leaving a raw phase label the initial README write may have
			// used.
			titleEdit, err := scalarFieldEdit(src, end, offset, fields["title"], ph.Title, "title", ph.Doc)
			if err != nil {
				return "", err
			}
			if titleEdit != nil {
				edits = append(edits, *titleEdit)
			}
		}
	}
	sort.Slice(edits, func(i, j int) bool { return edits[i].start > edits[j].start })
	for _, e := range edits {
		src = src[:e.start] + e.text + src[e.end:]
	}
	return src, nil
}

// scalarFieldEdit computes the edit (if any) that brings a README phase
// entry's plain- or quoted-scalar field to the wanted value, matching
// refreshReadmePhaseStatuses' status-field logic exactly so title and status
// stay in lockstep. Returns nil, nil when the field already holds want.
func scalarFieldEdit(src string, end int, offset func(*yaml.Node) (int, error), field *yaml.Node, want, fieldName, doc string) (*struct {
	start, end int
	text       string
}, error) {
	if field != nil && field.Kind == yaml.ScalarNode && field.Tag == "!!str" && field.Value == want {
		return nil, nil
	}
	if field == nil || field.Kind != yaml.ScalarNode || field.Tag != "!!str" || field.Anchor != "" || field.Style&(yaml.LiteralStyle|yaml.FoldedStyle|yaml.TaggedStyle) != 0 {
		return nil, fmt.Errorf("compile: generated phase %s requires a plain or quoted scalar %s", doc, fieldName)
	}
	start, err := offset(field)
	if err != nil {
		return nil, err
	}
	finish := start
	replacement := want
	switch field.Style {
	case yaml.DoubleQuotedStyle, yaml.SingleQuotedStyle:
		quote := src[start]
		if quote != '"' && quote != '\'' {
			return nil, fmt.Errorf("compile: quoted phase %s source span does not start at a quote", fieldName)
		}
		finish++
		for finish < end {
			if quote == '"' && src[finish] == '\\' {
				finish += 2
				continue
			}
			if src[finish] == quote {
				if quote == '\'' && finish+1 < end && src[finish+1] == '\'' {
					finish += 2
					continue
				}
				finish++
				break
			}
			finish++
		}
		if finish > end || src[finish-1] != quote {
			return nil, fmt.Errorf("compile: unterminated phase %s", fieldName)
		}
		if quote == '"' {
			replacement = strconv.Quote(want)
		} else {
			replacement = "'" + want + "'"
		}
	default:
		if !strings.HasPrefix(src[start:end], field.Value) || strings.ContainsAny(field.Value, "\r\n") {
			return nil, fmt.Errorf("compile: unsafe phase %s source span", fieldName)
		}
		finish = start + len(field.Value)
	}
	return &struct {
		start, end int
		text       string
	}{start, finish, replacement}, nil
}

func renderGraphViewSection(plan string, groups []phaseGroup) string {
	var b strings.Builder
	b.WriteString(graphViewBegin + "\n\n## Graph View\n\n")
	fmt.Fprintf(&b, "%s\n\n", viewMarker(plan))
	b.WriteString("| Phase | Nodes | Doc |\n|---|---|---|\n")
	total := 0
	for _, ph := range groups {
		fmt.Fprintf(&b, "| %d: %s | %d | `%s` |\n", ph.Ordinal, ph.Title, len(ph.Nodes), ph.Doc)
		total += len(ph.Nodes)
	}
	fmt.Fprintf(&b, "\n%d node(s) total. The committed graph (`%s-Graph.json`) is the source of\ntruth; these documents are projections.\n\n", total, plan)
	b.WriteString(graphViewEnd)
	return b.String()
}

// PathForView is exported for tests and callers that need to know where a
// phase group renders.
func PathForView(root, plan, doc string) string {
	return filepath.Join(root, "Plans", plan, doc)
}
